{"kind":"card","card":{"id":"c3","kind":"quiz","elements":[{"type":"text","id":"c3-q","content":"After pollen lands on the stigma, what grows down to reach the ovules?"},{"type":"button","id":"c3-a","label":"A pollen tube","actions":[{"type":"score","delta":1},{"type":"goto","cardId":"c4"}]},{"type":"button","id":"c3-b","label":"A root","actions":[{"type":"score","delta":0},{"type":"goto","cardId":"c4"}]},{"type":"button","id":"c3-c","label":"A thorn","actions":[{"type":"score","delta":0},{"type":"goto","cardId":"c4"}]}],"actions":[]}}
