{"kind":"card","card":{"id":"c5","kind":"story","elements":[{"type":"text","id":"c5-t","content":"Your light seeds float away on the wind and land far from home. Well done for spreading out!"},{"type":"button","id":"c5-b","label":"Continue","actions":[{"type":"goto","cardId":"c7"}]}],"actions":[]}}
{"kind":"card","card":{"id":"c6","kind":"story","elements":[{"type":"text","id":"c6-t","content":"A bird eats your sweet berry and drops the seed somewhere new. The seed can now grow in a fresh place."},{"type":"button","id":"c6-b","label":"Continue","actions":[{"type":"goto","cardId":"c7"}]}],"actions":[]}}
